package com.xmission.trevin.android.tangram.data;

import static com.xmission.trevin.android.tangram.data.CornerButtonModel.Control;
import static com.xmission.trevin.android.tangram.data.TangramPreferences.Corner;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

import java.util.EnumSet;

/**
 * Tests for {@link CornerButtonModel}: initial collision resolution and
 * the swap behavior when a control is moved into an occupied corner.
 *
 * @author Claude Opus 4.8
 */
public class CornerButtonModelTests {

    /** Assert that the model is a valid bijection over all four corners. */
    private static void assertBijection(CornerButtonModel model) {
        EnumSet<Control> seen = EnumSet.noneOf(Control.class);
        for (Corner corner : Corner.values()) {
            Control control = model.controlAt(corner);
            assertNotNull("every corner has a control", control);
            assertTrue("no control appears twice: " + control, seen.add(control));
            assertEquals("round-trips through cornerFor",
                    corner, model.cornerFor(control));
        }
        assertEquals("all four controls placed", 4, seen.size());
    }

    @Test
    public void defaultLayoutHonorsPreferences() {
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_RIGHT, Corner.BOTTOM_RIGHT);
        assertBijection(model);
        assertEquals(Corner.TOP_LEFT, model.cornerFor(Control.EXIT));
        assertEquals(Corner.TOP_RIGHT, model.cornerFor(Control.GOAL));
        assertEquals(Corner.BOTTOM_RIGHT, model.cornerFor(Control.SAVE));
        assertEquals(Corner.BOTTOM_LEFT, model.cornerFor(Control.NONE));
    }

    @Test
    public void collidingPreferencesResolveToAValidLayout() {
        // All three controls request the same corner.
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_LEFT, Corner.TOP_LEFT);
        assertBijection(model);
        // Exit has priority for the requested corner.
        assertEquals(Corner.TOP_LEFT, model.cornerFor(Control.EXIT));
    }

    @Test
    public void placeSwapsWithOccupant() {
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_RIGHT, Corner.BOTTOM_RIGHT);
        // Move Exit (TOP_LEFT) onto Goal (TOP_RIGHT); they should swap.
        assertTrue(model.place(Control.EXIT, Corner.TOP_RIGHT));
        assertEquals(Corner.TOP_RIGHT, model.cornerFor(Control.EXIT));
        assertEquals(Corner.TOP_LEFT, model.cornerFor(Control.GOAL));
        assertBijection(model);
    }

    @Test
    public void placeOntoEmptyCornerLeavesSourceEmpty() {
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_RIGHT, Corner.BOTTOM_RIGHT);
        // BOTTOM_LEFT is the empty (NONE) corner; move Save there.
        assertTrue(model.place(Control.SAVE, Corner.BOTTOM_LEFT));
        assertEquals(Corner.BOTTOM_LEFT, model.cornerFor(Control.SAVE));
        assertEquals(Corner.BOTTOM_RIGHT, model.cornerFor(Control.NONE));
        assertBijection(model);
    }

    @Test
    public void placeInSameCornerIsNoOp() {
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_RIGHT, Corner.BOTTOM_RIGHT);
        assertFalse(model.place(Control.EXIT, Corner.TOP_LEFT));
        assertEquals(Corner.TOP_LEFT, model.cornerFor(Control.EXIT));
    }

    @Test
    public void placeIsIdempotentBijectionAcrossManyMoves() {
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_RIGHT, Corner.BOTTOM_RIGHT);
        model.place(Control.GOAL, Corner.BOTTOM_LEFT);
        model.place(Control.SAVE, Corner.TOP_LEFT);
        model.place(Control.EXIT, Corner.BOTTOM_RIGHT);
        assertBijection(model);
    }

    @Test
    public void noneNeverMoves() {
        CornerButtonModel model = new CornerButtonModel(
                Corner.TOP_LEFT, Corner.TOP_RIGHT, Corner.BOTTOM_RIGHT);
        Corner emptyBefore = model.cornerFor(Control.NONE);
        assertFalse(model.place(Control.NONE, Corner.TOP_LEFT));
        assertEquals(emptyBefore, model.cornerFor(Control.NONE));
    }
}